import type { MapContinentId } from './worldMapData';

export type SeaAccessType =
  | 'Okeanga chiqadi'
  | 'Dengizga chiqadi'
  | 'Dengizga chiqmaydi'
  | 'Ikki marta dengizga chiqmaydi'
  | 'Orol davlati';

export interface SovereignStateBase {
  iso2: string;
  atlasName: string;
  nameUz: string;
  nameEn: string;
  capitalUz: string;
  continent: Exclude<MapContinentId, 'Antarktida'>;
  areaKm2: number;
  populationM: number; // in millions (e.g. 37.5, 0.0008 for Vatican)
  currencyUz: string;
  languagesUz: string;
  govFormUz: string;
  seaAccess: SeaAccessType;
  neighborsUz: string[];
  highestPeak: string;
  longestRiver: string;
  climateUz: string;
  resourcesUz: string;
  majorCitiesUz: string[];
  independenceUz: string;
  landmarksUz: string[];
  tourismUz: string;
  economyUz: string;
  lat: number;
  lng: number;
}

export interface FullCountryLesson extends SovereignStateBase {
  lessonDurationMin: number;
  coordinatesLabel: string;
  borderSummary: string;
  seaAccessDetail: string;
  tenGeoFacts: string[];
  fiveSurprisingFacts: string[];
  geoCharacteristics: string;
  uniqueDifferences: string;
  lastUpdated: string;
  sources: string[];
}

