function formatPopulationUz(popM: number): string {
  if (popM >= 1000) {
    return `${(popM / 1000).toFixed(2)} mlrd`;
  }
  if (popM >= 1) {
    return `${popM.toFixed(1)} mln`;
  }
  if (popM >= 0.01) {
    return `${Math.round(popM * 1000)} ming`;
  }
  return `${Math.round(popM * 1_000_000)} kishi`;
}

export function formatAreaUz(areaKm2: number): string {
  return `${areaKm2.toLocaleString('uz-UZ')} km²`;
}

export function formatCoordLabel(lat: number, lng: number): string {
  const latDir = lat >= 0 ? 'N' : 'S';
  const lngDir = lng >= 0 ? 'E' : 'W';
  return `${Math.abs(lat).toFixed(1)}° ${latDir}, ${Math.abs(lng).toFixed(1)}° ${lngDir}`;
}

function createTenGeoFacts(r: RawState): string[] {
  const [, , nameUz, , capitalUz, continent, areaKm2, popM, currencyUz, languagesUz, govFormUz, seaAccess, neighborsStr, highestPeak, longestRiver, climateUz, resourcesUz, citiesStr, independenceUz, landmarksStr] = r;
  const neighbors = neighborsStr.split('|').filter(Boolean);
  const cities = citiesStr.split('|').filter(Boolean);
  const landmarks = landmarksStr.split('|').filter(Boolean);
  const density = areaKm2 > 0 ? Math.round((popM * 1_000_000) / areaKm2) : 0;

  return [
    `${nameUz} ${continent} qit’asida joylashgan bo‘lib, rasmiy poytaxti ${capitalUz} shahridir.`,
    `Davlatning umumiy maydoni ${formatAreaUz(areaKm2)} ni tashkil qiladi.`,
    `Eng so‘nggi ma’lumotlarga ko‘ra aholisi ${formatPopulationUz(popM)} bo‘lib, o‘rtacha zichlik 1 km² ga ${density} kishiga to‘g‘ri keladi.`,
    `Geografik joylashuvi bo‘yicha ${nameUz} ${seaAccess.toLowerCase()} toifasiga kiradi.`,
    `Mamlakatning eng baland tabiiy nuqtasi — ${highestPeak}.`,
    `Asosiy suv arteriyalaridan biri — ${longestRiver}.`,
    `Hudud iqlimi asosan "${climateUz.toLowerCase()}" xususiyatiga ega.`,
    `Asosiy tabiiy boyliklari tarkibiga ${resourcesUz.toLowerCase()} kiradi.`,
    neighbors.length > 0
      ? `Chegara jihatidan ${neighbors.slice(0, 4).join(', ')} kabi hududlar bilan tutashgan.`
      : `Orol yoki alohida dengiz chegarasiga ega davlat sifatida qo‘shnilari bilan suv yo‘llari orqali bog‘lanadi.`,
    `Yirik shaharlari qatorida ${cities.join(', ')} alohida o‘rin tutadi; mashhur joylari: ${landmarks.join(', ')}.`,
  ];
}

function createFiveSurprisingFacts(r: RawState): string[] {
  const [, , nameUz, , capitalUz, continent, areaKm2, popM, currencyUz, languagesUz, govFormUz, seaAccess, , highestPeak, longestRiver, , , , independenceUz, landmarksStr] = r;
  const landmarks = landmarksStr.split('|').filter(Boolean);

  const seaNote =
    seaAccess === 'Ikki marta dengizga chiqmaydi'
      ? `${nameUz} dunyoda okeanga chiqish uchun kamida ikki davlat chegarasini kesib o‘tish shart bo‘lgan atigi ikkita davlatdan biridir.`
      : seaAccess === 'Dengizga chiqmaydi'
      ? `${nameUz} ochiq okeanga bevosita chiqa olmaydi, shu bois xalqaro savdoda qo‘shni tranzit yo‘laklariga tayanadi.`
      : seaAccess === 'Orol davlati'
      ? `${nameUz} quruqlik chegaralaridan ko‘ra dengiz ekotizimlari va portlariga tayanuvchi orol davlatidir.`
      : `${nameUz} to‘g‘ridan-to‘g‘ri xalqaro dengiz yoki okean savdo yo‘llariga chiqish imkoniyatiga ega.`;

  return [
    seaNote,
    `${nameUz}da "${languagesUz}" tili muloqotning asosini tashkil etadi, hisob-kitoblar esa "${currencyUz}" pul birligida yuritiladi.`,
    `Boshqaruv tizimi "${govFormUz}" shaklida tashkil etilgan bo‘lib, tarixiy burilish nuqtasi ${independenceUz} bilan bog‘liq.`,
    `${highestPeak} balandligi va ${longestRiver} kabi tabiiy obyektlar mamlakatning iqlimiy xilma-xilligini belgilaydi.`,
    `${landmarks[0] ?? capitalUz} kabi mashhur maskanlar har yili minglab sayyohlarni ${continent}ning bu burchagiga jalb qiladi (${areaKm2 < 1000 ? 'mitti hududga qaramay yuqori zichlikka ega' : popM > 80 ? 'aholisi 80 milliondan oshgan yirik davlat' : 'o‘ziga xos hududiy tuzilishga ega'}).`,
  ];
}

export const ALL_SOVEREIGN_COUNTRIES: FullCountryLesson[] = CLEAN_STATES_ALL.map(
  (r) => {
    const [
      iso2,
      atlasName,
      nameUz,
      nameEn,
      capitalUz,
      continent,
      areaKm2,
      populationM,
      currencyUz,
      languagesUz,
      govFormUz,
      seaAccess,
      neighborsStr,
      highestPeak,
      longestRiver,
      climateUz,
      resourcesUz,
      citiesStr,
      independenceUz,
      landmarksStr,
      economyUz,
      lat,
      lng,
    ] = r;

    const neighborsUz = neighborsStr.split('|').filter(Boolean);
    const majorCitiesUz = citiesStr.split('|').filter(Boolean);
    const landmarksUz = landmarksStr.split('|').filter(Boolean);

    return {
      iso2,
      atlasName,
      nameUz,
      nameEn,
      capitalUz,
      continent,
      areaKm2,
      populationM,
      currencyUz,
      languagesUz,
      govFormUz,
      seaAccess,
      neighborsUz,
      highestPeak,
      longestRiver,
      climateUz,
      resourcesUz,
      majorCitiesUz,
      independenceUz,
      landmarksUz,
      tourismUz: `${landmarksUz.join(', ')} kabi tabiiy va tarixiy maskanlar ${nameUz} turizmining asosiy yo‘nalishlarini tashkil qiladi.`,
      economyUz,
      lat,
      lng,
      lessonDurationMin: 8,
      coordinatesLabel: formatCoordLabel(lat, lng),
      borderSummary:
        seaAccess === 'Orol davlati'
          ? `Quruqlikda deyarli chegarasiz, dengiz va okean suvlari bilan o‘ralgan.`
          : `${neighborsUz.length} ta asosiy qo‘shni yo‘nalish bo‘ylab chegaradosh.`,
      seaAccessDetail:
        seaAccess === 'Ikki marta dengizga chiqmaydi'
          ? 'Ikki marta dengizga chiqmaydigan noyob geografik joylashuv (Double-landlocked).'
          : seaAccess === 'Dengizga chiqmaydi'
          ? 'Ichki qit’a joylashuvi (Landlocked) — ochiq okeanga chiqish yo‘li yo‘q.'
          : seaAccess === 'Orol davlati'
          ? 'Suv bilan o‘ralgan orol/arxipelag davlati.'
          : 'Ochiq dengiz yoki okean qirg‘og‘iga bevosita chiqadi.',
      tenGeoFacts: createTenGeoFacts(r),
      fiveSurprisingFacts: createFiveSurprisingFacts(r),
      geoCharacteristics: `${nameUz} ${continent}da ${formatCoordLabel(lat, lng)} koordinatalari atrofida joylashgan. Relyefida ${highestPeak} kabi balandliklar va ${longestRiver} havzasi muhim rol o‘ynaydi.`,
      uniqueDifferences: `${nameUz} boshqa davlatlardan ${climateUz.toLowerCase()} iqlimi, ${seaAccess.toLowerCase()} maqomi hamda ${economyUz.toLowerCase()} ixtisoslashuvi bilan ajralib turadi.`,
      lastUpdated: '2026-11',
      sources: ['UN Statistics Division', 'World Bank', 'UNESCO'],
    };
  }
);

export function formatCountryPopulation(popM: number): string {
  return formatPopulationUz(popM);
}
